const sleep = ms => new Promise(r => setTimeout(r, ms));
const tab = await (await fetch('http://127.0.0.1:9222/json/new?http://127.0.0.1:4173/', { method: 'PUT' })).json();
const ws = new WebSocket(tab.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
let nextId = 1; const pending = new Map();
ws.onmessage = e => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } };
function cdp(method, params = {}) { const id = nextId++; return new Promise(resolve => { pending.set(id, resolve); ws.send(JSON.stringify({ id, method, params })); }); }
async function evaluate(expression) { const r = await cdp('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true }); if (r.result.exceptionDetails) throw new Error(r.result.exceptionDetails.text); return r.result.result.value; }
await cdp('Page.enable'); await cdp('Runtime.enable'); await cdp('Network.enable'); await cdp('Page.navigate', { url: 'http://127.0.0.1:4173/' });
let ready = false;
for (let i=0;i<30;i++) { await sleep(500); try { ready = await evaluate("navigator.serviceWorker.ready.then(r => !!r.active && !!navigator.serviceWorker.controller)"); if (ready) break; } catch {} }
console.log('serviceWorkerReady=' + ready);
console.log('initialText=' + JSON.stringify((await evaluate('document.body.innerText')).slice(0,140)));
await cdp('Network.emulateNetworkConditions', { offline: true, latency: 0, downloadThroughput: 0, uploadThroughput: 0, connectionType: 'none' });
for (const route of ['/', '/forms', '/files', '/merged-files', '/spreadsheet', '/settings']) {
  await cdp('Page.navigate', { url: 'http://127.0.0.1:4173' + route }); await sleep(1200);
  const result = await evaluate('({ready:document.readyState,text:document.body.innerText.slice(0,100),controller:!!navigator.serviceWorker.controller})');
  console.log(route + '=' + JSON.stringify(result));
}
const idb = await evaluate("new Promise((resolve,reject)=>{const q=indexedDB.open('pwa-offline-isolated-test',1);q.onupgradeneeded=()=>q.result.createObjectStore('probe');q.onerror=()=>reject(q.error);q.onsuccess=()=>{const db=q.result;const tx=db.transaction('probe','readwrite');tx.objectStore('probe').put('ok','key');tx.oncomplete=()=>{const read=db.transaction('probe').objectStore('probe').get('key');read.onsuccess=()=>{resolve(read.result);db.close()}}}})");
console.log('isolatedIndexedDbWriteRead=' + idb);
ws.close();
